      equations: {"0": {"latex": "\\begin{aligned} 2(3x+y+2)+(x-2y-4)=0 &\\;\\text{எனவே}\\; P(0,-2) \\\\ 7(2y-3)-3y=-12 &\\;\\text{எனவே}\\; 11y=9,\\; Q\\left(-\\dfrac{15}{11},\\dfrac{9}{11}\\right) \\end{aligned}", "fallback": "P = (0, −2) from 3x + y + 2 = 0 மற்றும் x − 2y − 4 = 0; Q = (−15/11, 9/11) from 7x − 3y = −12 மற்றும் 2y = x + 3", "display": true}, "1": {"latex": "\\begin{aligned} \\dfrac{y - (-2)}{\\frac{9}{11} - (-2)} &= \\dfrac{x - 0}{-\\frac{15}{11} - 0} \\\\ \\dfrac{y+2}{31/11} &= \\dfrac{x}{-15/11} \\\\ -15(y+2) &= 31x \\\\ 31x + 15y + 30 &= 0 \\end{aligned}", "fallback": "(y + 2)/(31/11) = x/(−15/11) எனவே −15(y + 2) = 31x, எனவே 31x + 15y + 30 = 0", "display": true}}
